let fullscreenPending=false,fullscreenExitedAt=-Infinity;
const isFullscreen=()=>!!(document.fullscreenElement||document.webkitFullscreenElement);
const fullscreenLabel=()=>isFullscreen()?'退出全屏':'全屏';
function fullscreenIcon(){return `<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="${isFullscreen()?'M9 3v6H3m12-6v6h6M3 15h6v6m6 0v-6h6':'M9 3H3v6m12-6h6v6M3 15v6h6m6 0h6v-6'}"/></svg>`;}
function fullscreenButton(compact=false){return `<button class="fullscreen-toggle${compact?' fullscreen-compact':''}" data-act="fullscreen" aria-label="${fullscreenLabel()}" aria-pressed="${isFullscreen()}" title="${isFullscreen()?'退出全屏（Esc）':'全屏游玩 / 录制'}" ${fullscreenPending?'disabled':''}>${compact?fullscreenIcon():fullscreenLabel()}</button>`;}
function syncFullscreenButtons(){for(const b of ui.querySelectorAll('[data-act="fullscreen"]')){b.setAttribute('aria-label',fullscreenLabel());b.setAttribute('aria-pressed',String(isFullscreen()));b.title=isFullscreen()?'退出全屏（Esc）':'全屏游玩 / 录制';b.disabled=fullscreenPending;b.innerHTML=b.classList.contains('fullscreen-compact')?fullscreenIcon():fullscreenLabel();}}
async function toggleFullscreen(){
  if(fullscreenPending)return;
  fullscreenPending=true;syncFullscreenButtons();
  const exiting=isFullscreen();
  try{
    // Request in the click gesture, before any awaited operation. The root also
    // includes the toast layer, which lives outside #game.
    if(exiting){const exit=document.exitFullscreen||document.webkitExitFullscreen;if(!exit)throw new Error('unsupported');await exit.call(document);}
    else{const root=document.documentElement;if(root.requestFullscreen)await root.requestFullscreen({navigationUI:'hide'});else if(root.webkitRequestFullscreen)await root.webkitRequestFullscreen();else throw new Error('unsupported');}
  }catch{toast(exiting?'暂时无法退出全屏，可按 Esc 退出。':'当前窗口无法全屏，请在浏览器中单独打开游戏后重试。');}
  finally{fullscreenPending=false;syncFullscreenButtons();}
}
function fullscreenChanged(){
  if(!isFullscreen())fullscreenExitedAt=performance.now();
  reset();syncFullscreenButtons();resize();requestAnimationFrame(resize);
}
document.addEventListener('fullscreenchange',fullscreenChanged);
